MASK = 0xff

def rol8(v, c):
    c &= 7
    return ((v << c) | (v >> (8-c))) & 0xff if c else v & 0xff

def run(prog, flag):
    mem = bytearray(8)
    pc = 0
    ok = 1
    trace = []
    for step in range(100000):
        if pc >= len(prog):
            return False, mem, trace, 'out of program'
        op = prog[pc]
        if op == 0xe0:
            return (ok == 1), mem, trace, 'halt'
        if pc+2 >= len(prog):
            return False, mem, trace, 'truncated'
        a1 = prog[pc+1]
        a2 = prog[pc+2]
        if op == 0x24:
            mem[a1] = (mem[a1] + a2) & 0xff
        elif op == 0x9e:
            mem[a1] = (mem[a1] - a2) & 0xff
        elif op == 0x1d:
            mem[a1] = (mem[a1] * a2) & 0xff
        elif op == 0x7a:
            mem[a1] ^= a2
        elif op == 0xb2:
            mem[a1] = rol8(mem[a1], a2)
        elif op == 0xa7:
            if mem[a1] != a2:
                ok = 0
        elif op == 0x91:
            mem[a1] = flag[a2] if a2 < len(flag) else 0
        elif op == 0x6d:
            mem[a1] = (mem[a1] + mem[a2]) & 0xff
        elif op == 0x4e:
            mem[a1] ^= mem[a2]
        elif op == 0xc3:
            mem[a1] = (mem[a1] << 1) & 0xff
        elif op == 0x2c:
            mem[a1] = (mem[a1] >> 1) & 0xff
        elif op == 0xd0:
            # rotate right? guess
            v = mem[a1]
            mem[a1] = ((v >> 1) | (v << 7)) & 0xff
        else:
            return False, mem, trace, f'unknown op {op:02x} at {pc}'
        pc += 3
    return False, mem, trace, 'step limit'

